int8_t MapGrid::GetValue(int col, int row) const {
  if (!IsValidPixel(col, row)) {
    return kCellUnknown;
  }
  const size_t index = CellIndex(width, col, row);
  if (index >= data.size()) {
    return kCellUnknown;
  }
  return data[index];
}

